def current_receipt():
    """Authenticate deployed source at the original fresh-population boundary."""
    root = Path(__file__).resolve().parents[4]
    actual = {name: hashlib.sha256((root / name).read_bytes()).hexdigest()
              for name in _RELEASE['current_sources']}
    if actual != _RELEASE['current_sources']:
        raise ContractError('endpoint_prospective_dependency_mismatch')
    return deepcopy(_RELEASE)


def retained_current_receipt(receipt):
    """Compare this exact saved release without reading sources or recalculating."""
    return type(receipt) is dict and receipt == _RELEASE


def retained_v3_receipt(receipt):
    """Compare the exact accepted17 v3 release without current source IO."""
    return type(receipt) is dict and receipt == _HISTORICAL_V3_RELEASE


def retained_v2_receipt(receipt):
    """Compare the exact historical v2 release without current source IO."""
    return type(receipt) is dict and receipt == _HISTORICAL_V2_RELEASE
